'use strict';
const WORLD_PLACES=[
 {id:'forest',name:'霧語黑森林',kind:'forest',label:'FOREST',x:23,y:31,icon:'book',tag:'探索 · 溫習任務',description:'樹影之間閃着細小星光。每弄明白一個問題，迷霧就好似散開少少。'},
 {id:'peaks',name:'雲頂觀星台',kind:'mountain',label:'HIGHLANDS',x:48,y:22,icon:'star',tag:'觀察 · 發現新知',description:'沿着山路登上觀星台，帶住好奇心探索世界，收集今日嘅新發現。'},
 {id:'ruins',name:'古鐘地城',kind:'dungeon',label:'DUNGEON',x:72,y:32,icon:'shield',tag:'地城 · 知識試煉',description:'古老石門藏住數字同謎題。準備好紙筆，一步一步解開知識機關。'},
 {id:'castle',name:'星晶城堡',kind:'boss',label:'GREAT TRIALS',x:51,y:49,icon:'shield',tag:'考試 Boss · 成長里程碑',description:'大試煉之門正等待勇者。累積 EXP、完成準備任務，再迎接公會長安排嘅考試 Boss。'},
 {id:'valley',name:'月泉小村',kind:'village',label:'SPRING VALLEY',x:26,y:64,icon:'book',tag:'村莊 · 閱讀與練習',description:'石橋旁有一間安靜書屋。坐低讀一頁，可能就會遇到下一段好故事。'},
 {id:'port',name:'曦光港市集',kind:'shop',label:'HARBOUR MARKET',x:54,y:76,icon:'gem',tag:'城市 · 商店與補給',description:'帆船帶來遠方嘅紀念物。用任務賺返嚟嘅水晶，揀一件屬於你嘅冒險收藏。'},
 {id:'coast',name:'風燈海岸',kind:'coast',label:'LANTERN COAST',x:81,y:69,icon:'sun',tag:'海岸 · 語言與旅程',description:'燈塔照亮新航道。練習用新詞語表達，讓故事傳到更遠嘅地方。'}
];
const WORLD_SHOP=[
 {id:'harbour-compass',name:'海風指南針',price:60,icon:'star',description:'指針總指向下一個值得好奇嘅方向。'},
 {id:'moon-book',name:'月泉冒險手冊',price:80,icon:'book',description:'用來記低發現、疑問同新故事嘅精緻手冊。'},
 {id:'forest-shield',name:'翠葉守護盾',price:120,icon:'shield',description:'刻着森林葉紋嘅收藏裝備，紀念你一步一步嘅成長。'},
 {id:'starlight-lantern',name:'星光小提燈',price:100,icon:'sparkle',description:'一盞溫暖小燈，陪你記住每一段努力。'}
];
const previousWorldUpgrade=upgradeSave;
upgradeSave=function(){previousWorldUpgrade();data.worldVisited??=[];data.shopPurchases??=[]};upgradeSave();
function placeForQuest(q){if(WORLD_PLACES.some(p=>p.id===q.region))return q.region;return {中文:'forest',英文:'coast',數學:'ruins',常識:'peaks',閱讀:'valley',其他:'port'}[q.subject]||'valley'}
function questsAt(id){return data.quests.filter(q=>placeForQuest(q)===id)}
function pendingAt(id){return questsAt(id).filter(q=>!q.done).length}
function regionOptions(selected='auto'){return `<option value="auto" ${selected==='auto'?'selected':''}>按科目自動安排</option>${WORLD_PLACES.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.name}${p.kind==='shop'?' · 城市／商店':p.kind==='boss'?' · Boss 城堡':''}</option>`).join('')}`}
function buyWorldItem(id){if(sessionRole!=='child')return {ok:false,message:'請先以小朋友身份登入。'};const item=WORLD_SHOP.find(i=>i.id===id);if(!item)return {ok:false,message:'找不到這件收藏。'};if(data.shopPurchases.includes(id))return {ok:false,message:'你已經擁有呢件收藏。'};if(data.crystals<item.price)return {ok:false,message:'水晶未夠，完成任務後可以再返嚟。'};data.crystals-=item.price;data.shopPurchases.push(id);data.treasures.push({name:item.name,desc:item.description,shopId:id});logActivity('shop',item.name,`曦光港市集購買 · ${item.price} 水晶`);persist();return {ok:true,message:`已買到${item.name}，可以喺寶物收藏查看及裝備。`}}
function worldShopBody(){return `<div class="market-banner">${icon('gem')}<span>你嘅水晶 <strong>${data.crystals}</strong></span><small>收藏裝備可喺角色狀態查看；購買唔會影響學習分數。</small></div><div class="market-grid">${WORLD_SHOP.map(item=>{const owned=data.shopPurchases.includes(item.id);return `<article class="market-item"><div class="market-emblem">${icon(item.icon)}</div><h3>${item.name}</h3><p>${item.description}</p><span class="market-price">${icon('gem')} ${item.price}</span><button class="primary small-btn" data-world-buy="${item.id}" ${owned||data.crystals<item.price?'disabled':''}>${owned?'已收藏':data.crystals<item.price?'水晶不足':'購買收藏'}</button></article>`}).join('')}</div>`}
function worldQuestBody(place){const qs=questsAt(place.id);return `<div class="world-place-intro"><span class="section-kicker">${place.label}</span><p>${place.description}</p><small>${qs.filter(q=>q.done).length} / ${qs.length} 個當地任務已完成</small></div>${place.kind==='boss'?`<h3 class="small-heading">考試 Boss</h3>${bossCards()}`:''}${place.kind==='shop'?worldShopBody():''}<h3 class="small-heading">${place.kind==='shop'?'市集委託':'當地任務'}</h3>${qs.length?questRows(false,qs):'<p class="empty">呢度暫時未有新委託。<br>家長可以喺任務工房，將新任務安排到呢個地點。</p>'}`}
function enterWorldPlace(id){if(sessionRole!=='child')return;const place=WORLD_PLACES.find(p=>p.id===id);if(!place)return;if(!data.worldVisited.includes(id)){data.worldVisited.push(id);persist();if(page==='world')render()}lastFocus=document.querySelector(`[data-world-place="${id}"]`)||document.activeElement;openModal('world-place',worldQuestBody(place),place.name);const overlay=$('.overlay');if(overlay)overlay.dataset.worldPlace=id;}
function worldMap(){const remaining=data.quests.filter(q=>!q.done).length;return `<main class="world-screen"><header class="world-topbar"><button class="world-back" data-world="home">${icon('home')} 返回小屋</button>${brand()}<div class="world-wallet"><button class="world-avatar" data-action="stats" aria-label="查看角色狀態">${portrait(data.hero,'mini-portrait')}<span>Lv.${level()}</span></button><span>${icon('gem')} ${data.crystals}</span></div></header><div class="world-stage"><section class="world-canvas" aria-label="星海群島互動地圖"><div class="world-map-art" role="img" aria-label="以香港海岸、半島及島嶼輪廓為靈感的奇幻油畫地圖"></div><div class="world-map-shade"></div><div class="world-heading"><p>THE STARLIGHT ARCHIPELAGO</p><h1>星海群島</h1><span>揀一個地方，展開今日嘅冒險。</span></div><svg class="world-routes" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-hidden="true"><path d="M230 310Q340 200 480 220T720 320M480 220Q500 330 510 490M230 310Q330 410 510 490M720 320Q660 470 510 490M510 490Q490 650 540 760M540 760Q390 800 260 640M540 760Q720 850 810 690"/></svg>${WORLD_PLACES.map(p=>{const count=p.kind==='boss'?data.bosses.filter(b=>!b.defeated).length:pendingAt(p.id);return `<button class="world-pin pin-${p.kind}" style="left:${p.x}%;top:${p.y}%" data-world-place="${p.id}" aria-label="${p.name}，${p.tag}，${count}個未完成${p.kind==='boss'?'Boss':'任務'}"><span class="world-pin-orb">${icon(p.icon)}${count?`<i>${count}</i>`:''}</span><span class="world-pin-label"><strong>${p.name}</strong><small>${p.kind==='shop'?'商店 · 當地委託':p.kind==='boss'?'考試 Boss':`${count} 個待完成任務`}</small></span></button>`}).join('')}<aside class="world-journal"><span class="world-journal-icon">${icon('scroll')}</span><div><h2>冒險手記</h2><p>${remaining} 個任務等你探索 · 已到訪 ${data.worldVisited.length} / ${WORLD_PLACES.length} 個地點</p><small>金色標記係商店，紅色標記係 Boss 試煉。</small></div></aside><div class="world-map-signature">每一小步，都會拓闊你的世界。<br><small>虛構群島 · 輪廓靈感來自香港</small></div></section></div><div class="world-mobile-hint">${icon('arrow')} 地圖可以左右滑動，撳地點睇委託</div></main>`}
const baseWorldRoom=room;
room=function(){return baseWorldRoom().replace('class="hotspot h-door" data-action="quests"','class="hotspot h-door" data-world="open"')};
const baseWorldRender=render;
render=function(){if(page!=='world'){baseWorldRender();return}if(sessionRole!=='child'){page='login';baseWorldRender();return}if(actorMotion){cancelAnimationFrame(actorMotion);actorMotion=null}if(roomInterval){clearInterval(roomInterval);roomInterval=null}$('.overlay')?.remove();modal=null;$('#app').innerHTML=worldMap()};
const baseWorldMissionPanel=missionPanel;
missionPanel=function(){return baseWorldMissionPanel().replace('<label class="field" for="mission-mode">',`<label class="field" for="mission-region">冒險地點</label><select class="input" id="mission-region" name="region">${regionOptions()}</select><p class="subtle">任務會出現喺所選地圖位置，小朋友可以由當地出發。</p><label class="field" for="mission-mode">`)};
const baseWorldReview=reviewQuest;
reviewQuest=function(id){baseWorldReview(id);const q=data.quests.find(q=>q.id===id),form=$('#edit-mission-form');if(!q||!form)return;const section=document.createElement('div');section.className='region-edit';section.innerHTML=`<label class="field" for="edit-region">冒險地點</label><select class="input" id="edit-region" name="region">${regionOptions(q.region||'auto')}</select>`;form.prepend(section)};
const regionSubmissions=new WeakMap();
document.addEventListener('submit',e=>{if(sessionRole!=='parent')return;const f=e.target;if(f.id==='mission-form'||f.id==='edit-mission-form'){const region=new FormData(f).get('region');if(region==='auto'||WORLD_PLACES.some(p=>p.id===region))regionSubmissions.set(f,{region,id:f.dataset.id,ids:new Set(data.quests.map(q=>q.id))})}},true);
document.addEventListener('submit',e=>{if(sessionRole!=='parent')return;const saved=regionSubmissions.get(e.target);if(!saved)return;const q=e.target.id==='edit-mission-form'?data.quests.find(q=>q.id===saved.id):data.quests.find(q=>!saved.ids.has(q.id));if(q){q.region=saved.region;persist()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.world==='open'&&sessionRole==='child'){go('world');return}if(b.dataset.world==='home'&&sessionRole==='child'){go('room');return}if(b.dataset.worldPlace){enterWorldPlace(b.dataset.worldPlace);return}if(b.dataset.worldBuy&&sessionRole==='child'){const result=buyWorldItem(b.dataset.worldBuy);if(result.ok){render();enterWorldPlace('port')}notify(result.message)}},true);
render();
